package com.yeshoda.medical.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import java.util.*;
@Service public class AiService {private final WebClient client=WebClient.create("https://generativelanguage.googleapis.com"); @Value("${gemini.api.key:}") private String apiKey; @Value("${gemini.model:gemini-2.5-flash}") private String model;
 public String ask(String message){if(apiKey==null||apiKey.isBlank())return "Demo assistant: I can help with appointment booking, doctor specialties, and general health information. I cannot diagnose conditions or prescribe medicines. For severe or worsening symptoms, contact a qualified healthcare professional.\n\nYou asked: "+message; try{Map<String,Object> part=Map.of("text","You are a cautious medical appointment assistant. Give general health information only, never diagnose or prescribe. Encourage professional care for concerning symptoms. Keep the answer concise. User: "+message);Map<String,Object> content=Map.of("parts",List.of(part));Map<String,Object> body=Map.of("contents",List.of(content));Map response=client.post().uri("/v1beta/models/"+model+":generateContent?key="+apiKey).contentType(MediaType.APPLICATION_JSON).bodyValue(body).retrieve().bodyToMono(Map.class).block();List candidates=(List)response.get("candidates");if(candidates!=null&&!candidates.isEmpty()){Map c=(Map)candidates.get(0);Map co=(Map)c.get("content");List parts=(List)co.get("parts");return String.valueOf(((Map)parts.get(0)).get("text"));}return "I could not generate a response right now.";}catch(Exception e){return "AI service is temporarily unavailable. Please use the appointment features or contact a healthcare professional.";}}
}
